# code.py: Claude Code driving keypad for the Adafruit MacroPad RP2040
# Generated by MacroPad Layout Studio. Encoder press cycles layers.
# Key numbers run 0-11, row-major from the top-left (OLED at the top).
# Needs these herdr config.toml additions (paste from MacroPad Layout Studio):
#   [keys]
#   focus_agent = "prefix+shift+1..9"
#   next_agent = "prefix+period"
#   previous_agent = "prefix+comma"
#   last_pane = "prefix+semicolon"
#
#   [[keys.command]]
#   key = "prefix+shift+c"
#   type = "shell"
#   command = 'p=$("$HERDR_BIN_PATH" tab create --cwd "$HERDR_ACTIVE_PANE_CWD" --focus | jq -r .result.root_pane.pane_id) && "$HERDR_BIN_PATH" pane run "$p" "claude"'
#   description = "new Claude Code tab here"
#
#   [[keys.command]]
#   key = "prefix+shift+a"
#   type = "shell"
#   command = 'p=$("$HERDR_BIN_PATH" tab create --cwd "$HERDR_ACTIVE_PANE_CWD" --focus | jq -r .result.root_pane.pane_id) && "$HERDR_BIN_PATH" pane run "$p" "claude --resume"'
#   description = "resume Claude Code in a new tab"
# tally-layout: {"prefix":"CONTROL+B","brightness":0.3,"gap":0.08,"layers":[{"name":"DRIVE","cw":{"type":"combo","mods":[],"key":"DOWN_ARROW"},"ccw":{"type":"combo","mods":[],"key":"UP_ARROW"},"keys":[{"label":"ESC","color":"RED","action":{"type":"combo","mods":[],"key":"ESCAPE"}},{"label":"MODE","color":"BLUE","action":{"type":"combo","mods":["SHIFT"],"key":"TAB"}},{"label":"REWIND","color":"BLUE","action":{"type":"rewind"}},{"label":"YES","color":"AMBER","action":{"type":"combo","mods":[],"key":"ONE"}},{"label":"ALWAYS","color":"AMBER","action":{"type":"combo","mods":[],"key":"TWO"}},{"label":"NO","color":"AMBER","action":{"type":"combo","mods":[],"key":"THREE"}},{"label":"TAB","color":"WHITE","action":{"type":"combo","mods":[],"key":"TAB"}},{"label":"LOG","color":"WHITE","action":{"type":"combo","mods":["CONTROL"],"key":"O"}},{"label":"COMPCT","color":"WHITE","action":{"type":"text","text":"/compact","enter":true}},{"label":"ENTER","color":"GREEN","action":{"type":"combo","mods":[],"key":"ENTER"}},{"label":"TALK","color":"PURPLE","action":{"type":"hold","mods":[],"key":"RIGHT_ALT"}},{"label":"BG","color":"WHITE","action":{"type":"background"}}]},{"name":"FLEET","cw":{"type":"herdr","id":"next_agent"},"ccw":{"type":"herdr","id":"previous_agent"},"keys":[{"label":"A1","color":"WHITE","action":{"type":"herdr","id":"focus_agent","n":1}},{"label":"A2","color":"WHITE","action":{"type":"herdr","id":"focus_agent","n":2}},{"label":"A3","color":"WHITE","action":{"type":"herdr","id":"focus_agent","n":3}},{"label":"A4","color":"WHITE","action":{"type":"herdr","id":"focus_agent","n":4}},{"label":"A5","color":"WHITE","action":{"type":"herdr","id":"focus_agent","n":5}},{"label":"A6","color":"WHITE","action":{"type":"herdr","id":"focus_agent","n":6}},{"label":"ATTN","color":"AMBER","action":{"type":"herdr","id":"open_notification_target"}},{"label":"NEW","color":"BLUE","action":{"type":"herdr","id":"new_claude"}},{"label":"RESUME","color":"BLUE","action":{"type":"herdr","id":"resume_claude"}},{"label":"ZOOM","color":"BLUE","action":{"type":"herdr","id":"zoom"}},{"label":"LAST","color":"BLUE","action":{"type":"herdr","id":"last_pane"}},{"label":"ENTER","color":"GREEN","action":{"type":"combo","mods":[],"key":"ENTER"}}]}]}

import time
from adafruit_macropad import MacroPad

macropad = MacroPad()
KC = macropad.Keycode
kbd = macropad.keyboard
layout = macropad.keyboard_layout

# ---------------------------------------------------------------- config
HERDR_PREFIX = (KC.CONTROL, KC.B)   # must match keys.prefix in ~/.config/herdr/config.toml
DOUBLE_TAP_GAP = 0.08
BRIGHTNESS = 0.30

# ---------------------------------------------------------------- colors
OFF = (0, 0, 0)
RED = (255, 0, 0)
AMBER = (255, 110, 0)
YELLOW = (255, 200, 0)
GREEN = (0, 200, 0)
CYAN = (0, 180, 200)
BLUE = (0, 60, 255)
PURPLE = (140, 0, 255)
MAGENTA = (255, 0, 150)
WHITE = (60, 60, 60)
PRESS = (255, 255, 255)

# ---------------------------------------------------------------- primitives
def combo(*keys):
    """Press keys together, then release all."""
    try:
        kbd.press(*keys)
    finally:
        kbd.release_all()


def herdr(*keys):
    """herdr prefix, then a key in prefix mode."""
    combo(*HERDR_PREFIX)
    combo(*keys)


def rewind():
    """Double ESC opens Claude Code's rewind menu."""
    combo(KC.ESCAPE)
    time.sleep(DOUBLE_TAP_GAP)
    combo(KC.ESCAPE)


def background():
    """Ctrl+B backgrounds a running task. When Ctrl+B is also the herdr
    prefix, pressing it twice makes herdr send one through to the pane."""
    combo(KC.CONTROL, KC.B)
    if HERDR_PREFIX == (KC.CONTROL, KC.B):
        combo(KC.CONTROL, KC.B)


class Hold:
    """Key held down for as long as the pad key is pressed (push-to-talk)."""

    def __init__(self, *keys):
        self.keys = keys

    def down(self):
        kbd.press(*self.keys)

    def up(self):
        kbd.release(*self.keys)

    def __call__(self):
        # Encoder steps and other one-shot uses get a tap.
        combo(*self.keys)


# ---------------------------------------------------------------- layers
# Each key: (OLED label <= 6 chars, base color, action)
LAYERS = [
    {
        "name": "DRIVE",
        "keys": [
            ("ESC"    , RED,     lambda: combo(KC.ESCAPE)),
            ("MODE"   , BLUE,    lambda: combo(KC.SHIFT, KC.TAB)),
            ("REWIND" , BLUE,    rewind),
            ("YES"    , AMBER,   lambda: combo(KC.ONE)),
            ("ALWAYS" , AMBER,   lambda: combo(KC.TWO)),
            ("NO"     , AMBER,   lambda: combo(KC.THREE)),
            ("TAB"    , WHITE,   lambda: combo(KC.TAB)),
            ("LOG"    , WHITE,   lambda: combo(KC.CONTROL, KC.O)),
            ("COMPCT" , WHITE,   lambda: layout.write("/compact\n")),
            ("ENTER"  , GREEN,   lambda: combo(KC.ENTER)),
            ("TALK"   , PURPLE,  Hold(KC.RIGHT_ALT)),
            ("BG"     , WHITE,   background),
        ],
        "cw":  lambda: combo(KC.DOWN_ARROW),
        "ccw": lambda: combo(KC.UP_ARROW),
    },
    {
        "name": "FLEET",
        "keys": [
            ("A1"     , WHITE,   lambda: herdr(KC.SHIFT, KC.ONE)),
            ("A2"     , WHITE,   lambda: herdr(KC.SHIFT, KC.TWO)),
            ("A3"     , WHITE,   lambda: herdr(KC.SHIFT, KC.THREE)),
            ("A4"     , WHITE,   lambda: herdr(KC.SHIFT, KC.FOUR)),
            ("A5"     , WHITE,   lambda: herdr(KC.SHIFT, KC.FIVE)),
            ("A6"     , WHITE,   lambda: herdr(KC.SHIFT, KC.SIX)),
            ("ATTN"   , AMBER,   lambda: herdr(KC.O)),
            ("NEW"    , BLUE,    lambda: herdr(KC.SHIFT, KC.C)),
            ("RESUME" , BLUE,    lambda: herdr(KC.SHIFT, KC.A)),
            ("ZOOM"   , BLUE,    lambda: herdr(KC.Z)),
            ("LAST"   , BLUE,    lambda: herdr(KC.SEMICOLON)),
            ("ENTER"  , GREEN,   lambda: combo(KC.ENTER)),
        ],
        "cw":  lambda: herdr(KC.PERIOD),
        "ccw": lambda: herdr(KC.COMMA),
    },
]

# ---------------------------------------------------------------- display
def build_screen(layer):
    screen = macropad.display_text(title=layer["name"])
    labels = [k[0] for k in layer["keys"]]
    for row in range(4):
        a, b, c = labels[row * 3:row * 3 + 3]
        screen[row].text = "{:<7}{:<7}{:<6}".format(a, b, c)
    return screen


SCREENS = [build_screen(layer) for layer in LAYERS]

macropad.pixels.auto_write = False
macropad.pixels.brightness = BRIGHTNESS


def paint(layer):
    for i, key in enumerate(layer["keys"]):
        macropad.pixels[i] = key[1]
    macropad.pixels.show()


def activate(index):
    paint(LAYERS[index])
    SCREENS[index].show()


# ---------------------------------------------------------------- main loop
layer_index = 0
activate(layer_index)
last_position = macropad.encoder

while True:
    layer = LAYERS[layer_index]

    event = macropad.keys.events.get()
    if event:
        n = event.key_number
        action = layer["keys"][n][2]
        if event.pressed:
            macropad.pixels[n] = PRESS
            macropad.pixels.show()
            if isinstance(action, Hold):
                action.down()
            else:
                action()
        else:
            if isinstance(action, Hold):
                action.up()
            macropad.pixels[n] = layer["keys"][n][1]
            macropad.pixels.show()

    position = macropad.encoder
    if position != last_position:
        step = layer["cw"] if position > last_position else layer["ccw"]
        for _ in range(abs(position - last_position)):
            step()
        last_position = position

    macropad.encoder_switch_debounced.update()
    if macropad.encoder_switch_debounced.pressed:
        kbd.release_all()  # never leave a held key stuck across layers
        layer_index = (layer_index + 1) % len(LAYERS)
        activate(layer_index)
